import warnings
from fastapi import FastAPI

warnings.simplefilter("error", DeprecationWarning)

app = FastAPI()

@app.on_event("startup")
def startup_event():
    app.state.ready = True

@app.on_event("shutdown")
def shutdown_event():
    app.state.ready = False

@app.get("/status")
def get_status():
    return {"ready": getattr(app.state, "ready", False)}
